input.content:
:root {
  --bg-1: #0f1724;
  --bg-2: #1c2635;
  --panel: rgba(14, 18, 28, 0.83);
  --panel-alt: rgba(22, 32, 48, 0.85);
  --accent: #9bd8ff;
  --gold: #f6d58d;
  --success: #8fe3b2;
  --danger: #ff7d7d;
  --text: #edf5ff;
  --muted: #b8cfe8;
  --tile: #290f17;
  --tile-2: #3b1a27;
  --floor: #4f6f7b;
  --wall: #3c384d;
  --shadow: rgba(5, 5, 12, 0.48);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  background: radial-gradient(circle at top, #2a3450 0%, #141b2a 35%, var(--bg-1) 100%);
  color: var(--text);
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

button {
  border: 1px solid rgba(155, 216, 255, 0.45);
  background: linear-gradient(180deg, rgba(111, 167, 255, 0.25), rgba(85, 112, 164, 0.18));
  color: var(--text);
  border-radius: 12px;
  padding: 8px 14px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, filter 0.15s ease;
}

button:hover {
  transform: translateY(-1px);
  filter: brightness(1.15);
}

.game-shell {
  width: min(1400px, 100%);
  background: rgba(8, 13, 22, 0.72);
  border: 1px solid rgba(155, 216, 255, 0.18);
  border-radius: 22px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.38);
  overflow: hidden;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 24px;
  background: linear-gradient(180deg, rgba(27, 34, 52, 0.95), rgba(14, 21, 31, 0.9));
  border-bottom: 1px solid rgba(155, 216, 255, 0.12);
}

.eyebrow {
  margin: 0 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold);
  font-size: 0.72rem;
}

h1 {
  margin: 0;
  font-size: clamp(1.8rem, 2vw, 3rem);
}

.topbar-actions {
  display: flex;
  gap: 10px;
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(240px, 0.9fr);
  gap: 18px;
  padding: 18px;
}

.board-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.board-wrap {
  position: relative;
  background: linear-gradient(180deg, rgba(17, 25, 35, 0.96), rgba(13, 18, 27, 0.96));
  border: 1px solid rgba(155, 216, 255, 0.14);
  border-radius: 18px;
  overflow: hidden;
  min-height: 620px;
}

canvas {
  display: block;
  width: 100%;
  height: auto;
  background: linear-gradient(180deg, rgba(17, 25, 35, 0.9), rgba(13, 18, 27, 0.96));
}

.status-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(150px, 1fr));
  gap: 12px;
  padding: 12px 16px;
  border-radius: 14px;
  background: rgba(22, 31, 44, 0.9);
  border: 1px solid rgba(155, 216, 255, 0.12);
}

.label {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 4px;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.panel {
  background: var(--panel);
  border: 1px solid rgba(155, 216, 255, 0.12);
  border-radius: 16px;
  padding: 16px;
}

h2 {
  margin-top: 0;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
}

#storyText {
  margin: 0;
  line-height: 1.55;
  color: var(--muted);
}

#journalList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

#journalList li {
  background: rgba(255, 255, 255, 0.03);
  border-left: 3px solid rgba(155, 216, 255, 0.6);
  border-radius: 8px;
  padding: 8px 10px;
  line-height: 1.4;
  color: var(--text);
}

.hidden {
  display: none !important;
}

@media (max-width: 980px) {
  .layout {
    grid-template-columns: 1fr;
  }

  .board-wrap {
    min-height: 480px;
  }
}
@media (max-width: 560px) {
  body {
    padding: 12px;
  }
  .topbar {
    flex-direction: column;
    align-items: stretch;
  }
  .topbar-actions {
    justify-content: space-between;
  }
  .status-row {
    grid-template-columns: 1fr;
  }
}

