const state = {
  chapterIndex: 0,
  levelIndex: 0,
  turned: false,
  hasKey: false,
  gameOver: false,
  story: [],
  gameWon: false,
  lastMove: null
};

let currentLevel = null;

function cloneLevel(level) {
  return JSON.parse(JSON.stringify(level));
}

function getCurrentLevel() {
  return chapters[state.chapterIndex].levels[state.levelIndex];
}

function updateUI() {
  const chapter = chapters[state.chapterIndex];
  const level = chapter.levels[state.levelIndex];
  chapterLabel.textContent = chapter.name;
  levelLabel.textContent = `${state.levelIndex + 1}`;
  objectiveLabel.textContent = level.objective;
  storyText.textContent = chapter.story;

  journalList.innerHTML = '';
  const mainLog = document.createElement('li');
  mainLog.textContent = `Chapter ${state.chapterIndex + 1}: ${chapter.name}`;
  journalList.appendChild(mainLog);

  const objectiveLog = document.createElement('li');
  objectiveLog.textContent = `Objective: ${level.objective}`;
  journalList.appendChild(objectiveLog);

  if (state.hasKey) {
    const keyLog = document.createElement('li');
    keyLog.textContent = 'Recovered the hidden relic. The gate can now be opened.';
    journalList.appendChild(keyLog);
  }

  if (state.gameWon) {
    const winLog = document.createElement('li');
    winLog.textContent = 'Conclusion reached. Adrian Vale was erased, not killed; the Society rewrote history.';
    journalList.appendChild(winLog);
  }
}

function setLevel(levelIndex = state.levelIndex, chapterIndex = state.chapterIndex) {
  state.chapterIndex = chapterIndex;
  state.levelIndex = levelIndex;
  state.hasKey = false;
  state.gameOver = false;
  state.gameWon = false;
  state.lastMove = null;
  currentLevel = cloneLevel(chapters[chapterIndex].levels[levelIndex]);
  updateUI();
}

function isWall(x, y) {
  if (x < 0 || y < 0 || x >= currentLevel.size || y >= currentLevel.size) return true;
  return currentLevel.walls.some(([wx, wy]) => wx === x && wy === y);
}

function isPit(x, y) {
  return currentLevel.floorPits.some((p) => p.x === x && p.y === y);
}

function isExit(x, y) {
  return currentLevel.exit.x === x && currentLevel.exit.y === y;
}

function isKey(x, y) {
  return currentLevel.key.x === x && currentLevel.key.y === y;
}

function enemyAt(x, y) {
  return currentLevel.enemies.some((enemy) => enemy.x === x && enemy.y === y);
}

function resolveEnemyMovement() {
  if (!currentLevel || state.gameOver) return;

  currentLevel.enemies.forEach((enemy) => {
    const next = enemy.patrol[(enemy.patrolIndex ?? 0) + 1] || enemy.patrol[0];
    if (!next) return;

    const dx = next.x - enemy.x;
    const dy = next.y - enemy.y;
    const stepX = Math.sign(dx || 0);
    const stepY = Math.sign(dy || 0);
    const direct = { x: stepX, y: stepY };

    if (direct.x !== 0 || direct.y !== 0) {
      const targetX = enemy.x + direct.x;
      const targetY = enemy.y + direct.y;

      if (isWall(targetX, targetY) || isPit(targetX, targetY)) {
        enemy.patrolIndex = (enemy.patrolIndex ?? 0) + 1;
        return;
      }

      enemy.x = targetX;
      enemy.y = targetY;
      enemy.patrolIndex = (enemy.patrolIndex ?? 0) + 1;
      enemy.dir = direct;
    }

    const player = currentLevel.player;
    if (enemy.x === player.x && enemy.y === player.y) {
      state.gameOver = true;
      objectiveLabel.textContent = 'Evelyn was caught. Try again.';
      storyText.textContent = 'The guardian closes in before the truth can be reached. Evelyn must move more carefully.';
      journalList.innerHTML = '<li>You were spotted by a guardian.</li><li>Try a different route and watch enemy patrols.</li>';
    }
  });
}

function movePlayer(dx, dy) {
  if (!currentLevel || state.gameOver || state.gameWon) return;

  const nextX = currentLevel.player.x + dx;
  const nextY = currentLevel.player.y + dy;

  if (isWall(nextX, nextY)) return;
  if (isPit(nextX, nextY)) {
    state.gameOver = true;
    objectiveLabel.textContent = 'A collapse swallowed the route.';
    storyText.textContent = 'The floor gives way beneath Evelyn. She has to rethink the path.';
    journalList.innerHTML = '<li>The floor collapsed.</li><li>Watch for broken stone and unstable ledges.</li>';
    return;
  }

  if (enemyAt(nextX, nextY)) {
    state.gameOver = true;
    objectiveLabel.textContent = 'A guardian caught Evelyn.';
    storyText.textContent = 'The chamber springs to life. One false step is death in this forgotten place.';
    journalList.innerHTML = '<li>A guardian blocked the route.</li><li>Study enemy rhythm and avoid the patrol path.</li>';
    return;
  }

  currentLevel.player.x = nextX;
  currentLevel.player.y = nextY;
  state.lastMove = { dx, dy };

  if (isKey(currentLevel.player.x, currentLevel.player.y)) {
    state.hasKey = true;
    objectiveLabel.textContent = 'Relic recovered. Find the exit.';
    storyText.textContent = 'The hidden relic hums in Evelyn’s hand. The door ahead unlocks with a low metallic click.';
  }

  if (currentLevel.gate && currentLevel.player.x === currentLevel.gate.x && currentLevel.player.y === currentLevel.gate.y && state.hasKey) {
    objectiveLabel.textContent = 'The gate opens. Keep moving.';
  }

  resolveEnemyMovement();

  if (isExit(currentLevel.player.x, currentLevel.player.y) && state.hasKey) {
    const chapter = chapters[state.chapterIndex];
    const isFinalLevel = state.chapterIndex === chapters.length - 1 && state.levelIndex === chapter.levels.length - 1;
    if (isFinalLevel) {
      state.gameWon = true;
      state.gameOver = true;
      objectiveLabel.textContent = 'The truth is yours.';
      storyText.textContent = 'Evelyn realizes Adrian Vale did not vanish. He was erased by the Society of Silence, which hid the lost civilization to protect its own power.';
      journalList.innerHTML = '<li>Evelyn has recovered the final seal.</li><li>Final revelation: Adrian Vale was not the victim of fate; he was erased by the order that rewrote history.</li>';
    } else {
      const nextChapterIndex = state.chapterIndex + 1;
      const nextLevelIndex = 0;
      const nextChapter = chapters[nextChapterIndex];
      if (nextChapter) {
        setLevel(nextLevelIndex, nextChapterIndex);
        storyText.textContent = `New chapter unlocked: ${nextChapter.name}.`;
        objectiveLabel.textContent = nextChapter.levels[0].objective;
      }
    }
  }

  updateUI();
}

function drawTile(x, y, size, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * size, y * size, size, size);
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.strokeRect(x * size + 0.5, y * size + 0.5, size - 1, size - 1);
}

function drawGrid() {
  const level = currentLevel;
  const size = canvas.width / level.size;
  const tiles = [];

  for (let y = 0; y < level.size; y++) {
    for (let x = 0; x < level.size; x++) {
      const isEven = (x + y) % 2 === 0;
      drawTile(x, y, size, isEven ? '#2e3a53' : '#243249');
      tiles.push({ x, y });
    }
  }

  level.walls.forEach(([x, y]) => drawTile(x, y, size, '#4a415d'));
  level.floorPits.forEach((p) => {
    ctx.fillStyle = '#122733';
    ctx.fillRect(p.x * size + 9, p.y * size + 9, size - 18, size - 18);
    ctx.fillStyle = '#6bd1ff';
    ctx.fillRect(p.x * size + 18, p.y * size + 18, size - 36, size - 36);
  });

  if (level.gate) {
    const g = level.gate;
    ctx.fillStyle = (state.hasKey && currentLevel.player.x === g.x && currentLevel.player.y === g.y) || state.hasKey ? '#9fe5b5' : '#6d4958';
    ctx.fillRect(g.x * size + 12, g.y * size + 12, size - 24, size - 24);
  }

  const exit = level.exit;
  ctx.fillStyle = '#d4b45e';
  ctx.fillRect(exit.x * size + 10, exit.y * size + 10, size - 20, size - 20);

  const key = level.key;
  if (!state.hasKey || (state.hasKey && !(currentLevel.player.x === key.x && currentLevel.player.y === key.y))) {
    ctx.fillStyle = '#f0d286';
    ctx.beginPath();
    ctx.arc((key.x + 0.5) * size, (key.y + 0.5) * size, size * 0.18, 0, Math.PI * 2);
    ctx.fill();
  }

  level.enemies.forEach((enemy) => {
    ctx.fillStyle = '#ff7b73';
    ctx.beginPath();
    ctx.arc((enemy.x + 0.5) * size, (enemy.y + 0.5) * size, size * 0.24, 0, Math.PI * 2);
    ctx.fill();
  });

  const player = currentLevel.player;
  ctx.fillStyle = '#9bd8ff';
  ctx.beginPath();
  ctx.arc((player.x + 0.5) * size, (player.y + 0.5) * size, size * 0.22, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#dfe8f4';
  ctx.font = 'bold 16px sans-serif';
  ctx.fillText('EXIT', (exit.x + 0.08) * size, (exit.y + 0.68) * size);
  if (state.hasKey) {
    ctx.fillStyle = '#9fe5b5';
    ctx.fillText('UNLOCKED', (currentLevel.gate.x + 0.08) * size, (currentLevel.gate.y + 0.68) * size);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (!currentLevel) return;
  drawGrid();
}

function handleKeydown(event) {
  const keyMap = {
    ArrowUp: [0, -1],
    ArrowDown: [0, 1],
    ArrowLeft: [-1, 0],
    ArrowRight: [1, 0],
    w: [0, -1],
    s: [0, 1],
    a: [-1, 0],
    d: [1, 0]
  };

  const move = keyMap[event.key] || keyMap[event.key.toLowerCase()];
  if (!move) return;
  event.preventDefault();
  movePlayer(move[0], move[1]);
}

function bindTouchControls() {
  const controls = [
    { label: '↑', dx: 0, dy: -1 },
    { label: '↓', dx: 0, dy: 1 },
    { label: '←', dx: -1, dy: 0 },
    { label: '→', dx: 1, dy: 0 }
  ];
  const pad = document.createElement('div');
  pad.style.position = 'fixed';
  pad.style.bottom = '18px';
  pad.style.left = '50%';
  pad.style.transform = 'translateX(-50%)';
  pad.style.display = 'grid';
  pad.style.gridTemplateColumns = 'repeat(3, 56px)';
  pad.style.gap = '8px';
  document.body.appendChild(pad);

  const blank = document.createElement('div');
  pad.appendChild(blank);

  controls.forEach((control) => {
    const btn = document.createElement('button');
    btn.textContent = control.label;
    btn.style.width = '56px';
    btn.style.height = '56px';
    btn.addEventListener('click', () => movePlayer(control.dx, control.dy));
    if (control.label === '↑') pad.appendChild(btn);
    if (control.label === '↓') pad.appendChild(btn);
    if (control.label === '←') pad.appendChild(btn);
    if (control.label === '→') pad.appendChild(btn);
  });
}

restartBtn.addEventListener('click', () => {
  setLevel(state.levelIndex, state.chapterIndex);
  render();
});

toggleJournalBtn.addEventListener('click', () => {
  const sidebar = document.querySelector('.sidebar');
  sidebar.classList.toggle('hidden');
  toggleJournalBtn.textContent = sidebar.classList.contains('hidden') ? 'Show Journal' : 'Hide Journal';
});

document.addEventListener('keydown', handleKeydown);

setLevel(0, 0);
render();
bindTouchControls();

setInterval(() => {
  render();
}, 1000 / 30);

