er-radius:10px;padding:38px 42px;box-shadow:0 25px 90px #000b}.ending-seal{font-size:42px;color:var(--gold);margin-bottom:13px}.ending-card h2{font:500 30px var(--serif);margin:8px 0 13px}.ending-card>p:not(.eyebrow){font-size:14px;line-height:1.75;color:#bbc1af}.ending-stats{margin:18px auto;color:#d9c491;font:12px var(--mono)}.ending-card button{background:#c9a767;border:0;border-radius:4px;padding:12px 18px;font:600 12px var(--sans);color:#171b17;cursor:pointer}
