253: function isWall(x, y) {
254:   if (x < 0 || y < 0 || x >= currentLevel.size || y >= currentLevel.size) return true;
255:   return currentLevel.walls.some(([wx, wy]) => wx === x && wy === y);
256: }
257: 
258: function isPit(x, y) {
259:   return currentLevel.floorPits.some((p) => p.x === x && p.y === y);
260: }
261: 
262: function isExit(x, y) {
263:   return currentLevel.exit.x === x && currentLevel.exit.y === y;
264: }
265: 
266: function isKey(x, y) {
267:   return currentLevel.key.x === x && currentLevel.key.y === y;
268: }
