274: function resolveEnemyMovement() {
275:   if (!currentLevel || state.gameOver) return;
276: 
277:   currentLevel.enemies.forEach((enemy) => {
278:     const next = enemy.patrol[(enemy.patrolIndex ?? 0) + 1] || enemy.patrol[0];
279:     if (!next) return;
280: 
281:     const dx = next.x - enemy.x;
282:     const dy = next.y - enemy.y;
283:     const stepX = Math.sign(dx || 0);
284:     const stepY = Math.sign(dy || 0);
285:     const direct = { x: stepX, y: stepY };
286: 
287:     if (direct.x !== 0 || direct.y !== 0) {
288:       const targetX = enemy.x + direct.x;
289:       const targetY = enemy.y + direct.y;
290: 
291:       if (isWall(targetX, targetY) || isPit(targetX, targetY)) {
292:         enemy.patrolIndex = (enemy.patrolIndex ?? 0) + 1;
293:         return;
294:       }
295: 
296:       enemy.x = targetX;
297:       enemy.y = targetY;
298:       enemy.patrolIndex = (enemy.patrolIndex ?? 0) + 1;
299:       enemy.dir = direct;
300:     }
301: 
302:     const player = currentLevel.player;
303:     if (enemy.x === player.x && enemy.y === player.y) {
304:       state.gameOver = true;
305:       objectiveLabel.textContent = 'Evelyn was caught. Try again.';
306:       storyText.textContent = 'The guardian closes in before the truth can be reached. Evelyn must move more carefully.';
307:       journalList.innerHTML = '<li>You were spotted by a guardian.</li><li>Try a different route and watch enemy patrols.</li>';
308:     }
309:   });
310: }
