312: function movePlayer(dx, dy) {
313:   if (!currentLevel || state.gameOver || state.gameWon) return;
314: 
315:   const nextX = currentLevel.player.x + dx;
316:   const nextY = currentLevel.player.y + dy;
317: 
318:   if (isWall(nextX, nextY)) return;
319:   if (isPit(nextX, nextY)) {
320:     state.gameOver = true;
321:     objectiveLabel.textContent = 'A collapse swallowed the route.';
322:     storyText.textContent = 'The floor gives way beneath Evelyn. She has to rethink the path.';
323:     journalList.innerHTML = '<li>The floor collapsed.</li><li>Watch for broken stone and unstable ledges.</li>';
324:     return;
325:   }
326: 
327:   if (enemyAt(nextX, nextY)) {
328:     state.gameOver = true;
329:     objectiveLabel.textContent = 'A guardian caught Evelyn.';
330:     storyText.textContent = 'The chamber springs to life. One false step is death in this forgotten place.';
331:     journalList.innerHTML = '<li>A guardian blocked the route.</li><li>Study enemy rhythm and avoid the patrol path.</li>';
332:     return;
333:   }
334: 
335:   currentLevel.player.x = nextX;
336:   currentLevel.player.y = nextY;
337:   state.lastMove = { dx, dy };
338: 
339:   if (isKey(currentLevel.player.x, currentLevel.player.y)) {
340:     state.hasKey = true;
341:     objectiveLabel.textContent = 'Relic recovered. Find the exit.';
342:     storyText.textContent = 'The hidden relic hums in Evelyn’s hand. The door ahead unlocks with a low metallic click.';
343:   }
344: 
345:   if (currentLevel.gate && currentLevel.player.x === currentLevel.gate.x && currentLevel.player.y === currentLevel.gate.y && state.hasKey) {
346:     objectiveLabel.textContent = 'The gate opens. Keep moving.';
347:   }
348: 
349:   resolveEnemyMovement();
350: 
351:   if (isExit(currentLevel.player.x, currentLevel.player.y) && state.hasKey) {
352:     const chapter = chapters[state.chapterIndex];
353:     const isFinalLevel = state.chapterIndex === chapters.length - 1 && state.levelIndex === chapter.levels.length - 1;
354:     if (isFinalLevel) {
