356:       state.gameOver = true;
357:       objectiveLabel.textContent = 'The truth is yours.';
358:       storyText.textContent = 'Evelyn realizes Adrian Vale did not vanish. He was erased by the Society of Silence, which hid the lost civilization to protect its own power.';
359:       journalList.innerHTML = '<li>Evelyn has recovered the final seal.</li><li>Final revelation: Adrian Vale was not the victim of fate; he was erased by the order that rewrote history.</li>';
360:     } else {
361:       const nextChapterIndex = state.chapterIndex + 1;
362:       const nextLevelIndex = 0;
363:       const nextChapter = chapters[nextChapterIndex];
364:       if (nextChapter) {
365:         setLevel(nextLevelIndex, nextChapterIndex);
366:         storyText.textContent = `New chapter unlocked: ${nextChapter.name}.`;
367:         objectiveLabel.textContent = nextChapter.levels[0].objective;
368:       }
369:     }
370:   }
371: 
372:   updateUI();
373: }
