375: function drawTile(x, y, size, color) {
376:   ctx.fillStyle = color;
377:   ctx.fillRect(x * size, y * size, size, size);
378:   ctx.strokeStyle = 'rgba(255,255,255,0.06)';
379:   ctx.strokeRect(x * size + 0.5, y * size + 0.5, size - 1, size - 1);
