382: function drawGrid() {
383:   const level = currentLevel;
384:   const size = canvas.width / level.size;
385:   const tiles = [];
386: 
387:   for (let y = 0; y < level.size; y++) {
388:     for (let x = 0; x < level.size; x++) {
389:       const isEven = (x + y) % 2 === 0;
390:       drawTile(x, y, size, isEven ? '#2e3a53' : '#243249');
391:       tiles.push({ x, y });
392:     }
393:   }
394: 
395:   level.walls.forEach(([x, y]) => drawTile(x, y, size, '#4a415d'));
396:   level.floorPits.forEach((p) => {
397:     ctx.fillStyle = '#122733';
398:     ctx.fillRect(p.x * size + 9, p.y * size + 9, size - 18, size - 18);
399:     ctx.fillStyle = '#6bd1ff';
400:     ctx.fillRect(p.x * size + 18, p.y * size + 18, size - 36, size - 36);
401:   });
402: 
403:   if (level.gate) {
404:     const g = level.gate;
405:     ctx.fillStyle = (state.hasKey && currentLevel.player.x === g.x && currentLevel.player.y === g.y) || state.hasKey ? '#9fe5b5' : '#6d4958';
406:     ctx.fillRect(g.x * size + 12, g.y * size + 12, size - 24, size - 24);
407:   }
408: 
409:   const exit = level.exit;
410:   ctx.fillStyle = '#d4b45e';
411:   ctx.fillRect(exit.x * size + 10, exit.y * size + 10, size - 20, size - 20);
412: 
413:   const key = level.key;
414:   if (!state.hasKey || (state.hasKey && !(currentLevel.player.x === key.x && currentLevel.player.y === key.y))) {
415:     ctx.fillStyle = '#f0d286';
416:     ctx.beginPath();
417:     ctx.arc((key.x + 0.5) * size, (key.y + 0.5) * size, size * 0.18, 0, Math.PI * 2);
418:     ctx.fill();
419:   }
420: 
421:   level.enemies.forEach((enemy) => {
422:     ctx.fillStyle = '#ff7b73';
423:     ctx.beginPath();
424:     ctx.arc((enemy.x + 0.5) * size, (enemy.y + 0.5) * size, size * 0.24, 0, Math.PI * 2);
425:     ctx.fill();
426:   });
427: 
428:   const player = currentLevel.player;
429:   ctx.fillStyle = '#9bd8ff';
430:   ctx.beginPath();
431:   ctx.arc((player.x + 0.5) * size, (player.y + 0.5) * size, size * 0.22, 0, Math.PI * 2);
432:   ctx.fill();
433: 
434:   ctx.fillStyle = '#dfe8f4';
435:   ctx.font = 'bold 16px sans-serif';
436:   ctx.fillText('EXIT', (exit.x + 0.08) * size, (exit.y + 0.68) * size);
437:   if (state.hasKey) {
438:     ctx.fillStyle = '#9fe5b5';
439:     ctx.fillText('UNLOCKED', (currentLevel.gate.x + 0.08) * size, (currentLevel.gate.y + 0.68) * size);
440:   }
441: }
